#!/usr/bin/env node
// Downloads a curated set of official Rive sample .riv files into the native
// demo (examples/native) and writes its gallery manifest (data/examples.js).
//
//   npm run fetch:examples
//
// All files are public Rive demo assets (rive.app CDN / rive-flutter examples),
// chosen to exercise different runtime features: interactive state machines,
// number inputs + listeners, and plain looping animations.

import { mkdirSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
// Downloads the demo .riv files for the NATIVE example app. (.riv live in the
// subpackage; the manifest is a main-package JS module so the gallery can
// require it before the subpackage downloads.) The Taro demo inlines its own
// copies as base64 via examples/taro/scripts/inline-riv.mjs.
const NATIVE = join(__dirname, '..', 'examples', 'native', 'miniprogram');
const ASSET_DIR = join(NATIVE, 'pkgRive', 'assets', 'riv');
const DATA_DIR = join(NATIVE, 'data');

const EXAMPLES = [
  {
    file: 'vehicles.riv',
    url: 'https://cdn.rive.app/animations/vehicles.riv',
    title: 'Vehicles',
    subtitle: '状态机 · 点击切换',
    tags: ['状态机', '交互'],
  },
  {
    file: 'off_road_car.riv',
    url: 'https://cdn.rive.app/animations/off_road_car_v7.riv',
    title: 'Off-Road Car',
    subtitle: '状态机 · 触发弹跳',
    tags: ['状态机', '交互'],
  },
  {
    file: 'skills.riv',
    url: 'https://raw.githubusercontent.com/rive-app/rive-flutter/master/example/assets/skills.riv',
    title: 'Skills',
    subtitle: '数字输入 · 监听器',
    tags: ['状态机', '输入'],
  },
  {
    file: 'little_machine.riv',
    url: 'https://raw.githubusercontent.com/rive-app/rive-flutter/master/example/assets/little_machine.riv',
    title: 'Little Machine',
    subtitle: '状态机 · 触摸驱动',
    tags: ['状态机', '交互'],
  },
  {
    file: 'marty.riv',
    url: 'https://cdn.rive.app/animations/marty.riv',
    title: 'Marty',
    subtitle: '角色循环动画',
    tags: ['动画'],
  },
  {
    file: 'rocket.riv',
    url: 'https://raw.githubusercontent.com/rive-app/rive-flutter/master/example/assets/rocket.riv',
    title: 'Rocket',
    subtitle: '轻量循环动画',
    tags: ['动画'],
  },
];

async function download(url) {
  const res = await fetch(url, { redirect: 'follow' });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return Buffer.from(await res.arrayBuffer());
}

async function main() {
  mkdirSync(ASSET_DIR, { recursive: true });
  const manifest = [];
  for (const ex of EXAMPLES) {
    process.stdout.write(`[fetch-examples] ${ex.file} … `);
    try {
      const buf = await download(ex.url);
      writeFileSync(join(ASSET_DIR, ex.file), buf);
      console.log(`ok (${(buf.length / 1024).toFixed(1)} KB)`);
      manifest.push({
        file: ex.file,
        path: `/pkgRive/assets/riv/${ex.file}`,
        title: ex.title,
        subtitle: ex.subtitle,
        tags: ex.tags,
        source: ex.url,
        bytes: buf.length,
      });
    } catch (e) {
      console.log(`FAILED (${e.message})`);
    }
  }
  mkdirSync(DATA_DIR, { recursive: true });
  const js =
    '// AUTO-GENERATED by tools/fetch-examples.mjs — do not edit.\n' +
    '// Gallery manifest (main package). The .riv files live in /pkgRive/assets/riv/.\n' +
    'module.exports = ' + JSON.stringify(manifest, null, 2) + ';\n';
  writeFileSync(join(DATA_DIR, 'examples.js'), js);
  console.log(`[fetch-examples] wrote ${manifest.length} examples -> examples/native/miniprogram/data/examples.js`);
  const total = manifest.reduce((a, b) => a + b.bytes, 0);
  console.log(`[fetch-examples] total .riv size: ${(total / 1024).toFixed(1)} KB`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
